":1,\"totalValue42\":1,\"sources\":{\"cosmos\":{\"count\":1,\"totalValue42\":1}}},{\"a\":\"0xc3CFeC4aCa0E2E4206185129A0Ac3ED764d4BC03\",\"b\":\"0xeb59b392a5558931354e574D3B3bEafF44f9df81\",\"count\":2,\"totalValue42\":2001,\"sources\":{\"cosmos\":{\"count\":2,\"totalValue42\":2001}}},{\"a\":\"0x40c8e5Bbb51cD6a4BCC9E13F19d2b39FAcF0233B\",\"b\":\"0xeb59b392a5558931354e574D3B3bEafF44f9df81\",\"count\":1,\"totalValue42\":1000,\"sources\":{\"cosmos\":{\"count\":1,\"totalValue42\":1000}}},{\"a\":\"0x855Df84e2867899A51D8A517156E1C89c55ce446\",\"b\":\"0xDAC5Fcc3B9C0f965888b346cf27faAD5F90Da274\",\"count\":5,\"totalValue42\":795,\"sources\":{\"cosmos\":{\"count\":5,\"totalValue42\":795}}},{\"a\":\"0x65b18070198Ef86DF379dd695AC8Cb350Cd2d03F\",\"b\":\"0x85996A6b22ea606Af88DaBd184681B5776e86f0D\",\"count\":2,\"totalValue42\":2228,\"sources\":{\"cosmos\":{\"count\":2,\"totalValue42\":2228}}},{\"a\":\"0x4E75d8bdE2965Ac4CFdF5a1d9B2F4D9B77B4181d\",\"b\":\"0x79b7bf240f6be95937704e2Edd8e73F8f43564EB\",\"count\":1,\"totalValue42\":1,\"sources\":{\"cosmos\":{\"count\":1,\"totalValue42\":1}}},{\"a\":\"0x7E99B2886e16F8aC32610b0C8542C01eE7872b12\",\"b\":\"0xc3CFeC4aCa0E2E4206185129A0Ac3ED764d4BC03\",\"count\":2,\"totalValue42\":11,\"sources\":{\"cosmos\":{\"count\":2,\"totalValue42\":11}}},{\"a\":\"0xbfc5Dd3A9434BeD286853f03B353eaCde6d84F29\",\"b\":\"0xc3CFeC4aCa0E2E4206185129A0Ac3ED764d4BC03\",\"count\":2,\"totalValue42\":11,\"sources\":{\"cosmos\":{\"count\":2,\"totalValue42\":11}}},{\"a\":\"0x3D37D8F3EC1C9F58708070cF80Ad600d1084401d\",\"b\":\"0xc3CFeC4aCa0E2E4206185129A0Ac3ED764d4BC03\",\"count\":1,\"totalValue42\":0.02,\"sources\":{\"cosmos\":{\"count\":1,\"totalValue42\":0.02}}},{\"a\":\"0xD3349CaC126Ce02cA481e6a1ae8CC8d3AD46aA4D\",\"b\":\"0xea1Adb4dEF61eD581d77D7F380CAFA5d757881b2\",\"count\":1,\"totalValue42\":1450,\"sources\":{\"cosmos\":{\"count\":1,\"totalValue42\":1450}}},{\"a\":\"0x855Df84e2867899A51D8A517156E1C89c55ce446\",\"b\":\"0xE5a3b887D09F5477025B0044849cFcce5C076fD1\",\"count\":1,\"totalValue42\":0.5,\"sources\":{\"cosmos\":{\"count\":1,\"totalValue42\":0.5}}},{\"a\":\"0x114b0267342Df640139915d295E106E3Bba87F40\",\"b\":\"0x855Df84e2867899A51D8A517156E1C89c55ce446\",\"count\":1,\"totalValue42\":200,\"sources\":{\"cosmos\":{\"count\":1,\"totalValue42\":200}}},{\"a\":\"0x6039672428EFea0ed045c8ada438d783E2f7d50E\",\"b\":\"0x855Df84e2867899A51D8A517156E1C89c55ce446\",\"count\":1,\"totalValue42\":2,\"sources\":{\"cosmos\":{\"count\":1,\"totalValue42\":2}}},{\"a\":\"0xAD41107E260541c237D943487ea73F2040c7dAf4\",\"b\":\"0xfa1243BAc322255cAb763aE0bcfb6AF0f85F95fB\",\"count\":1,\"totalValue42\":501,\"sources\":{\"cosmos\":{\"count\":1,\"totalValue42\":501}}},{\"a\":\"0x7FbBad54901A8e309FA8C6A43A51a3Ab1980e816\",\"b\":\"0x855Df84e2867899A51D8A517156E1C89c55ce446\",\"count\":1,\"totalValue42\":30,\"sources\":{\"cosmos\":{\"count\":1,\"totalValue42\":30}}},{\"a\":\"0x9d6ED0365145FfdA3216f6a3B81848F1D82FaF99\",\"b\":\"0xC774634546A8baa8cb9534157d0a373cc3Ea4392\",\"count\":2,\"totalValue42\":1640,\"sources\":{\"cosmos\":{\"count\":2,\"totalValue42\":1640}}},{\"a\":\"0x65b18070198Ef86DF379dd695AC8Cb350Cd2d03F\",\"b\":\"0xd8272f7f61B3f6E1cFcD9f5BB98FCaDb1c807bFa\",\"count\":1,\"totalValue42\":1001,\"sources\":{\"cosmos\":{\"count\":1,\"totalValue42\":1001}}}]};\n//__DATA_END__\n\nif (!DATA) {\n  document.getElementById('nodata').style.display = 'grid';\n  throw new Error('no snapshot');\n}\n\n/* ---------------- helpers ---------------- */\nconst $ = (id) => document.getElementById(id);\nconst shortAddr = (a) => a.slice(0, 6) + '…' + a.slice(-4);\nfunction fmt42(v) {\n  if (v >= 1000) return v.toLocaleString('ja-JP', { maximumFractionDigits: 2 });\n  if (v >= 1) return v.toLocaleString('ja-JP', { maximumFractionDigits: 4 });\n  if (v > 0) return v.toLocaleString('ja-JP', { maximumFractionDigits: 6 });\n  return '0';\n}\nfunction fmtDate(iso) {\n  const d = new Date(iso);\n  return d.toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });\n}\n\n/* ---------------- clusters (union-find) ---------------- */\nconst nodes = DATA.nodes.map((n, i) => ({ ...n, idx: i, x: 0, y: 0, vx: 0, vy: 0, r: 0, cluster: -1 }));\nconst byAddr = new Map(nodes.map((n) => [n.address.toLowerCase(), n]));\n/* Cluster coloring is a DISPLAY-ONLY choice — nodes, edges and the layout\n   physics never change, only which addresses share a color:\n   A 'all'        : union over ALL edges. Hub contracts (DEX router/pairs)\n                    glue everyone together — the v4 view, where 221\n                    addresses incl. 12 validators collapsed into one\n                    cluster through the router. Data-correct, but the\n                    colors stop meaning much.\n   B 'nocontract' : union over edges whose BOTH endpoints are EOAs only.\n                    Contracts never act as connectors (paths run through\n                    EOAs only) and each contract is a neutral singleton,\n                    so a hub contract can't merge the map into one color.\n                    DEFAULT — the most informative view.\n   C 'direct'     : a colored group forms only when EVERY member directly\n                    transacted with EVERY other member (either source),\n                    built greedily from the largest edges; everyone else\n                    stays a singleton. The strictest \"who sent to whom\".\n                    EXCEPTION (standing rule): any direct edge touching a\n                    validator ALWAYS forms a cluster link, however small\n                    the amount — validator dust sends are tracked in\n                    every mode, no exceptions.\n   D 'core'       : like B, plus distributor-pattern EOAs (flagged by the\n                    fetcher: same exact amount sent to >= 10 distinct\n                    recipients — e.g. an operator seeding 2 [42] to\n                    everyone) are ALSO excluded as connectors and shown\n                    as neutral singletons. This is the one opt-in mode\n                    where a distributor's seed edges do not glue. The\n                    excluded addresses are named in the legend.\n   There is NO minimum-amount threshold anywhere: every recorded\n   transfer counts, dust included.\n   In every mode a validator keeps its gold ring + ★, and validator\n   clusters (even a lone validator) get a real color, never the gray\n   (the only exception: a distributor-flagged address in mode D is\n   neutral-filled by design — its ★ ring and name still show). */\nlet clusterMode = 'nocontract';\nlet clusterMembers = new Map();\nlet multiClusters = [];\nlet clusterColor = new Map();\nconst SINGLE_COLOR = '#5b7290';\nconst HUES = [16, 45, 80, 120, 160, 190, 210, 245, 275, 305, 330, 0];\nconst MODE_LABELS = { all: '全つながり', nocontract: 'コントラクト経由を除く', direct: '直接送金のみ', core: '中核アドレスを除く' };\nconst MODE_INFO = {\n  all: 'クラスター判定: 全ての送金で判定（コントラクト経由を含む）',\n  nocontract: 'クラスター判定: コントラクト経由のつながりは数えない（EOA同士の連鎖のみ）',\n  direct: 'クラスター判定: 全員が互いに直接送金したグループのみ色付け（バリデーター関連は少額でも常に追跡）',\n  core: 'クラスター判定: コントラクト＋中核（配布型）アドレス経由のつながりを数えない',\n};\n/* Core categories (user ruling, 2026-10-31 — \"aとbは排除で\"):\n   A = system contracts (DEX router/factory/pairs, TOWEL, Guide,\n       Starlight, st42 vault, marketplace, QNS, precompiles, fee\n       collector, bridge router…) — caught by the isContract flag,\n       no list needed; glue-excluded in B and D, lines hideable.\n   B = distributor/operator-type: the fetcher's distributor rule\n       (Xenia) PLUS the addresses designated here. The dormant #1\n       holder (1.9M [42], EVM txCount 0) is designated: it has no\n       EVM history but DOES hold 9 Cosmos edges in this snapshot\n       (incl. 140,764 [42] with Xenia), so the designation has a\n       real effect — in mode D it stops gluing, and the hub-line\n       toggle hides those edges. It stays an ordinary node in B.\n   C (unidentified high-frequency relay EOAs) and D (active\n   validators) are deliberately NOT core: they stay tracked. */\nconst DESIGNATED_CORE = {\n  '0xebc32e52a1aa52d8a0cd71402c4ffdf316f0db07': 'Starlight',\n  '0x7a6f6d4e0ce3abbba5ab6685c37a9599f6250a25': '残高1位アドレス',\n};\nfunction isDesignatedCore(n) { return !!DESIGNATED_CORE[n.address.toLowerCase()]; }\nfunction computeClusters(mode) {\n  const groups = new Map();\n  const put = (root, n) => { n.cluster = root; if (!groups.has(root)) groups.set(root, []); groups.get(root).push(n); };\n  const eoaPair = (e) => {\n    const a = byAddr.get(e.a.toLowerCase()), b = byAddr.get(e.b.toLowerCase());\n    return (a && b && !a.isContract && !b.isContract) ? { a, b } : null;\n  };\n  if (mode === 'direct') {\n    /* Phase 1 (standing rule, no amount exceptions): every direct edge\n       touching a validator unions its endpoints — a 2 [42] seed send\n       links a validator exactly like a 100,000 [42] transfer does. */\n    const parent = nodes.map((_, i) => i);\n    const find = (x) => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };\n    const union = (a, b) => { a = find(a); b = find(b); if (a !== b) parent[a] = b; };\n    for (const e of DATA.edges) {\n      const p = eoaPair(e);\n      if (p && (p.a.validator || p.b.validator)) union(p.a.idx, p.b.idx);\n    }\n    const compSize = new Map();\n    for (const n of nodes) { const r = find(n.idx); compSize.set(r, (compSize.get(r) || 0) + 1); }\n    const locked = new Set(nodes.filter((n) => compSize.get(find(n.idx)) >= 2).map((n) => n.idx));\n    /* Phase 2: mutual-direct groups among the remaining (unlocked) EOAs,\n       over non-validator edges only (validator edges are phase 1). */\n    const pairSet = new Set();\n    const cand = [];\n    for (const e of DATA.edges) {\n      const p = eoaPair(e);\n      if (!p || p.a.validator || p.b.validator) continue;\n      pairSet.add(p.a.idx < p.b.idx ? p.a.idx + '|' + p.b.idx : p.b.idx + '|' + p.a.idx);\n      cand.push({ a: p.a, b: p.b, total: e.totalValue42 });\n    }\n    cand.sort((x, y) => y.total - x.total);\n    const linked = (i, j) => pairSet.has(i < j ? i + '|' + j : j + '|' + i);\n    const groupOf = new Map(); // node idx -> shared member-idx array\n    for (const { a, b } of cand) {\n      if (locked.has(a.idx) || locked.has(b.idx)) continue;\n      const ga = groupOf.get(a.idx), gb = groupOf.get(b.idx);\n      if (!ga && !gb) {\n        const g = [a.idx, b.idx];\n        groupOf.set(a.idx, g); groupOf.set(b.idx, g);\n      } else if (ga && !gb) {\n        if (ga.every((m) => linked(b.idx, m))) { ga.push(b.idx); groupOf.set(b.idx, ga); }\n      } else if (!ga && gb) {\n        if (gb.every((m) => linked(a.idx, m))) { gb.push(a.idx); groupOf.set(a.idx, gb); }\n      }\n      // both already grouped: no merge — keeps the mutual-direct rule strict.\n    }\n    for (const n of nodes) {\n      if (locked.has(n.idx)) { put(find(n.idx), n); continue; }\n      const g = groupOf.get(n.idx);\n      put(g ? Math.min(...g) : n.idx, n);\n    }\n    return groups;\n  }\n  const parent = nodes.map((_, i) => i);\n  const find = (x) => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };\n  const union = (a, b) => { a = find(a); b = find(b); if (a !== b) parent[a] = b; };\n  for (const e of DATA.edges) {\n    const a = byAddr.get(e.a.toLowerCase()), b = byAddr.get(e.b.toLowerCase());\n    if (!a || !b) continue;\n    if (mode === 'nocontract' && (a.isContract || b.isContract)) continue;\n    /* Mode D: contracts, distributor-flagged EOAs AND designated-core\n       addresses (category A+B) never act as glue. */\n    if (mode === 'core' && (a.isContract || b.isContract || a.distributor || b.distributor || isDesignatedCore(a) || isDesignatedCore(b))) continue;\n    union(a.idx, b.idx);\n  }\n  for (const n of nodes) put(find(n.idx), n);\n  return groups;\n}\n/* colors: distinct hues, assigned in priority order —\n   1) multi-node clusters that contain a validator (however small),\n   2) the remaining multi-node clusters by size rank,\n   3) lone validators (a validator on its own still gets a real color,\n      never the anonymous gray, so its ★ identity stays visible).\n   Only non-validator singletons fall back to the gray SINGLE_COLOR. */\nfunction recluster(mode) {\n  clusterMode = mode;\n  clusterMembers = computeClusters(mode);\n  const clustersSorted = [...clusterMembers.entries()]\n    .map(([root, members]) => ({ root, members, total: members.reduce((s, m) => s + m.balance, 0) }))\n    .sort((a, b) => b.members.length - a.members.length || b.total - a.total);\n  multiClusters = clustersSorted.filter((c) => c.members.length >= 2);\n  clusterColor = new Map();\n  const hasValidator = (c) => c.members.some((m) => m.validator);\n  const colorOrder = [\n    ...multiClusters.filter(hasValidator),\n    ...multiClusters.filter((c) => !hasValidator(c)),\n    ...clustersSorted.filter((c) => c.members.length === 1 && hasValidator(c)),\n  ];\n  colorOrder.forEach((c, i) => {\n    clusterColor.set(c.root, i < HUES.length\n      ? `hsl(${HUES[i]}, 78%, 62%)`\n      : `hsl(${(i * 47) % 360}, 55%, 55%)`);\n  });\n  for (const n of nodes) n.color = clusterColor.get(n.cluster) || SINGLE_COLOR;\n  /* Mode D only: distributor-flagged addresses are neutral-filled even\n     when they are validators (their ★ ring / badge / name still draw —\n     only the cluster color is suppressed, by the user's explicit opt-in). */\n  if (mode === 'core') for (const n of nodes) if (n.distributor || isDesignatedCore(n)) n.color = SINGLE_COLOR;\n}\nrecluster(clusterMode);\n\n/* ---------------- view filters (v6, display-only) ----------------\n   Two independent display filters layered over the cluster modes.\n   Neither changes nodes, edges, positions, physics or cluster\n   assignment — only what draw()/pick()/fitToBubbles() present.\n   1) Hub lines: \"hub nodes\" are the addresses the mode system already\n      treats as infrastructure rather than people — contract nodes\n      (DEX router/pairs) plus distributor-flagged EOAs (mode D's core,\n      e.g. Xenia). Hiding their edges is what makes mode D readable:\n      in v5 the excluded hubs stopped GLUING clusters but their lines\n      were still drawn, leaving a web of purple spokes. The hub\n      bubbles themselves stay drawn and tappable; only the lines go.\n      Default: hidden in mode D, shown in modes A/B/C; the toggle in\n      the header can flip it in any mode.\n   2) Mode E 「クラスターのみ」: hides every address that is a\n      SINGLETON under the active cluster mode (bubble + its edges),\n      leaving only multi-address clusters. Standing-rule exception:\n      validators (★) are ALWAYS shown, even when singleton. */\nlet hubLinesVisible = true;\nlet clusterOnly = false;\n/* Hub nodes for the line toggle = category A (contracts) + category\n   B (distributor-flagged and designated-core addresses). */\nconst isHubNode = (n) => !!(n.isContract || n.distributor || isDesignatedCore(n));\nconst edgeTouchesHub = (e) => isHubNode(e.a) || isHubNode(e.b);\nfunction nodeShown(n) {\n  if (!clusterOnly) return true;\n  if (n.validator) return true;\n  const m = clusterMembers.get(n.cluster);\n  return !!m && m.length >= 2;\n}\nfunction hiddenCount() {\n  let c = 0;\n  for (const n of nodes) if (!nodeShown(n)) c++;\n  return c;\n}\nfunction setHubLines(v) {\n  hubLinesVisible = !!v;\n  const btn = $('hubbtn');\n  if (btn) {\n    btn.textContent = hubLinesVisible ? '中核の線: 表示' : '中核の線: 非表示';\n    btn.classList.toggle('on', hubLinesVisible);\n  }\n}\nfunction setClusterOnly(on) {\n  clusterOnly = !!on;\n  const btn = $('eonlybtn');\n  if (btn) btn.classList.toggle('on', clusterOnly);\n  refreshFilterInfo();\n  if (selectedNode && !nodeShown(selectedNode)) clearSelection();\n  fitToBubbles();\n}\nfunction refreshFilterInfo() {\n  const el = $('filterinfo');\n  if (!el) return;\n  el.textContent = clusterOnly\n    ? `クラスターのみ表示中: 単独アドレス ${hiddenCount()} 件を非表示（★バリデーターは単独でも表示しています）`\n    : '';\n}\n\n/* ---------------- sizes & layout ---------------- */\nconst maxBal = Math.max(...nodes.map((n) => n.balance));\n/* Radius ∝ sqrt(balance) — area-true, NO additive base. The old formula\n   (max(5, 46*sqrt(...))) floored every node below ~22k 42 at the same\n   r=5 world units, so ranks ~9-150 were literally identical in size and\n   even #3 sat within 1.5x of the tail. Only a tiny epsilon floor remains\n   here; the visible minimum is the draw-level 2.2px floor (drawRadiusW),\n   and the single largest bubble is capped at fit time in fitToBubbles. */\nconst R_MAX = 125;\nfor (const n of nodes) n.r = Math.max(0.5, R_MAX * Math.sqrt(n.balance / maxBal));\nconst W0 = 2400, H0 = 1600;\nnodes.forEach((n, i) => {\n  const ang = (i / nodes.length) * Math.PI * 2;\n  const rad = 260 + (i % 17) * 55;\n  n.x = W0 / 2 + Math.cos(ang) * rad;\n  n.y = H0 / 2 + Math.sin(ang) * rad * 0.66;\n});\nconst edgeList = DATA.edges.map((e) => ({\n  a: byAddr.get(e.a.toLowerCase()), b: byAddr.get(e.b.toLowerCase()), count: e.count, total: e.totalValue42,\n  sources: e.sources || { evm: { count: e.count, totalValue42: e.totalValue42 } },\n})).filter((e) => e.a && e.b);\n/* Per-node direct connections with their per-source aggregates, for the\n   tooltip and the tap panel (\"is this link EVM / Cosmos / both?\"). */\nconst connByNode = new Map(nodes.map((n) => [n, []]));\nfor (const e of edgeList) {\n  connByNode.get(e.a).push({ other: e.b, sources: e.sources });\n  connByNode.get(e.b).push({ other: e.a, sources: e.sources });\n}\nfunction srcLabel(s) {\n  const parts = [];\n  if (s.evm) parts.push(`<span class=\"src src-evm\">EVM ${s.evm.count}件・${fmt42(s.evm.totalValue42)} 42</span>`);\n  if (s.cosmos) parts.push(`<span class=\"src src-cosmos\">Cosmos ${s.cosmos.count}件・${fmt42(s.cosmos.totalValue42)} 42</span>`);\n  return parts.join(' ／ ');\n}\n\n/* ---------------- canvas / view ---------------- */\nconst cv = $('cv'), ctx = cv.getContext('2d');\nlet view = { x: 0, y: 0, k: 1 };\nfunction resize() {\n  const dpr = Math.min(window.devicePixelRatio || 1, 2);\n  cv.width = Math.round(innerWidth * dpr); cv.height = Math.round(innerHeight * dpr);\n  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n}\n/* Fit the actual bubble bounding box into the visible area below the header.\n   Runs after the warmup, on every resize/orientation change, and from the\n   「全体を表示」 button — the full scene can always be recovered with it. */\nfunction fitToBubbles() {\n  const iw = innerWidth, ih = innerHeight;\n  if (!nodes.length || iw < 10 || ih < 10) return;\n  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;\n  for (const n of nodes) {\n    if (!nodeShown(n)) continue; // Mode E: frame what is actually visible\n    if (!isFinite(n.x) || !isFinite(n.y)) continue;\n    const rr = n.r + 6;\n    if (n.x - rr < minX) minX = n.x - rr;\n    if (n.y - rr < minY) minY = n.y - rr;\n    if (n.x + rr > maxX) maxX = n.x + rr;\n    if (n.y + rr > maxY) maxY = n.y + rr;\n  }\n  if (!isFinite(minX) || !isFinite(minY)) return;\n  const bw = Math.max(10, maxX - minX), bh = Math.max(10, maxY - minY);\n  const headerEl = document.querySelector('header');\n  const topPad = (headerEl ? headerEl.getBoundingClientRect().height : 0) + 8;\n  const availW = Math.max(50, iw - 16);\n  const availH = Math.max(80, ih - topPad - 14);\n  view.k = Math.min(4, Math.max(0.02, Math.min(availW / bw, availH / bh)));\n  /* Cap ONLY the extreme top: the largest bubble's on-screen radius at\n     fit zoom must stay around 10-13% of the viewport width, so #1 reads\n     as huge without swallowing the map. Zooming further OUT keeps the\n     whole bounding box inside the view, so this can only shrink k. */\n  let maxR = 0;\n  for (const n of nodes) if (nodeShown(n) && n.r > maxR) maxR = n.r;\n  const capK = (iw * 0.12) / Math.max(1, maxR);\n  if (view.k > capK) view.k = capK;\n  view.x = iw / 2 - ((minX + maxX) / 2) * view.k;\n  view.y = topPad + availH / 2 - ((minY + maxY) / 2) * view.k;\n}\nfunction onResize() {\n  try { resize(); fitToBubbles(); } catch (e) { /* the render loop retries */ }\n}\naddEventListener('resize', onResize);\naddEventListener('orientationchange', () => setTimeout(onResize, 80));\nresize();\nconst toWorld = (sx, sy) => ({ x: (sx - view.x) / view.k, y: (sy - view.y) / view.k });\nconst toScreen = (wx, wy) => ({ x: view.x + wx * view.k, y: view.y + wy * view.k });\n/* Single source of truth for a bubble's on-screen size: drawing AND\n   hit-testing both go through drawRadiusW, so a tap always lands on\n   exactly the circle that is painted (2.2px minimum on-screen radius). */\nconst MIN_R_PX = 2.2, TAP_MIN_PX = 20;\nconst drawRadiusW = (n) => Math.max(n.r, MIN_R_PX / Math.max(view.k, 0.05));\n\n/* ---------------- force simulation ---------------- */\nlet simRunning = true, stillFrames = 0;\nlet userInteracted = false, appStarted = false;\n/* Force integration, hardened after the v1 blow-up: the old uncapped\n   2600/d² repulsion (with d recomputed inconsistently in the overlap\n   branch) injected so much energy that coordinates overflowed to\n   ±Infinity within ~11 frames and every node turned NaN — canvas then\n   silently draws nothing. Forces and velocities are now hard-capped,\n   the spring is linear in distance, and any non-finite state is\n   sanitised per node before it can spread. */\nfunction step() {\n  const N = nodes.length;\n  for (let i = 0; i < N; i++) {\n    const a = nodes[i];\n    for (let j = i + 1; j < N; j++) {\n      const b = nodes[j];\n      let dx = a.x - b.x, dy = a.y - b.y;\n      let d2 = dx * dx + dy * dy;\n      if (d2 < 1) { const ang = Math.random() * Math.PI * 2; dx = Math.cos(ang); dy = Math.sin(ang); d2 = 1; }\n      const d = Math.sqrt(d2);\n      const minD = a.r + b.r + 6;\n      let f = 900 / d2;\n      if (d < minD) f += (minD - d) * 0.06;\n      if (f > 4) f = 4;\n      const fx = dx / d * f, fy = dy / d * f;\n      a.vx += fx; a.vy += fy; b.vx -= fx; b.vy -= fy;\n    }\n  }\n  for (const e of edgeList) {\n    const dx = e.b.x - e.a.x, dy = e.b.y - e.a.y;\n    const d = Math.max(1, Math.hypot(dx, dy));\n    const rest = e.a.r + e.b.r + 46;\n    let f = (d - rest) * 0.004;\n    if (f > 1.5) f = 1.5; else if (f < -1.5) f = -1.5;\n    const fx = dx / d * f, fy = dy / d * f;\n    e.a.vx += fx; e.a.vy += fy; e.b.vx -= fx; e.b.vy -= fy;\n  }\n  let maxV = 0;\n  for (const n of nodes) {\n    n.vx += (W0 / 2 - n.x) * 0.002;\n    n.vy += (H0 / 2 - n.y) * 0.002;\n    if (dragNode === n) continue;\n    n.vx *= 0.85; n.vy *= 0.85;\n    const sp = Math.hypot(n.vx, n.vy);\n    if (sp > 24) { n.vx = n.vx / sp * 24; n.vy = n.vy / sp * 24; }\n    n.x += n.vx; n.y += n.vy;\n    if (!isFinite(n.x) || !isFinite(n.y) || !isFinite(n.vx) || !isFinite(n.vy)) {\n      n.x = W0 / 2 + (Math.random() - 0.5) * 200; n.y = H0 / 2 + (Math.random() - 0.5) * 200;\n      n.vx = 0; n.vy = 0;\n    }\n    if (n.x < -3000) n.x = -3000; else if (n.x > W0 + 3000) n.x = W0 + 3000;\n    if (n.y < -3000) n.y = -3000; else if (n.y > H0 + 3000) n.y = H0 + 3000;\n    maxV = Math.max(maxV, Math.abs(n.vx), Math.abs(n.vy));\n  }\n  if (maxV < 0.05) {\n    if (++stillFrames > 40) {\n      simRunning = false;\n      if (appStarted && !userInteracted) fitToBubbles();\n    }\n  } else stillFrames = 0;\n}\nfunction wake() { simRunning = true; stillFrames = 0; }\n\n/* ---------------- interaction ---------------- */\nlet dragNode = null, panning = null, hover = null, selectedCluster = null, selectedNode = null, flashNode = null, flashUntil = 0;\nlet lastTap = { t: 0, x: -1e9, y: -1e9 }; // last tap handled in the pointerup path (click dedupe)\n/* Nearest-node picking, in screen space: a point selects the bubble whose\n   CENTER is nearest, provided that center is within max(drawn radius,\n   20px) of the point. The 20px floor makes even the tiniest (2.2px)\n   bubbles individually tappable in dense areas — the old rule\n   (distance < radius + 12px, nearest wins) could leave a floor-size\n   bubble unselectable when a bigger neighbour's disc overlapped the tap.\n   Ties (centers within 0.5px) go to the larger balance. */\nfunction pick(sx, sy) {\n  let best = null, bestD = Infinity;\n  for (const n of nodes) {\n    if (!nodeShown(n)) continue; // hidden (Mode E) bubbles are not tappable\n    if (!isFinite(n.x) || !isFinite(n.y)) continue;\n    const p = toScreen(n.x, n.y);\n    const d = Math.hypot(p.x - sx, p.y - sy);\n    const rPx = drawRadiusW(n) * Math.max(view.k, 0.05);\n    if (d > Math.max(rPx, TAP_MIN_PX)) continue;\n    if (d < bestD - 0.5 || (best && d <= bestD + 0.5 && n.balance > best.balance)) {\n      best = n; bestD = Math.min(bestD, d);\n    }\n  }\n  return best;\n}\n/* Pointer Events でマウス / タッチ / ペンを統一。\n   タッチ: 1本指ドラッグ = 移動、ピンチ = 拡大縮小、タップ = 選択＋ツールチップ固定表示。 */\nconst pointers = new Map();\nlet pinch = null, lastPointerType = 'mouse';\nconst tipEl = $('tooltip');\nfunction tipHTML(n) {\n  const csize = clusterMembers.get(n.cluster).length;\n  const conns = connByNode.get(n) || [];\n  const connLine = conns.length\n    ? `<br>つながり: ${conns.length} アドレス（EVM ${conns.filter((c) => c.sources.evm).length} / Cosmos ${conns.filter((c) => c.sources.cosmos).length}）`\n    : '';\n  return (n.validator ? `<span class=\"lbl\">★ バリデーター: ${n.validator.moniker}</span><br>` : '') +\n    (n.name ? `<span class=\"lbl\">${n.name}</span>${n.isContract ? '（コントラクト）' : ''}<br>` : (n.isContract ? 'コントラクト<br>' : '')) +\n    `${n.address}<br>` +\n    `<span class=\"bal\">${fmt42(n.balance)} 42</span><br>` +\n    `クラスター: ${csize >= 2 ? csize + ' アドレス' : '単独'} / 取引数: ${n.txCount}` + connLine;\n}\nfunction showTip(n, sx, sy) {\n  tipEl.innerHTML = tipHTML(n);\n  tipEl.style.display = 'block';\n  tipEl.style.left = Math.max(4, Math.min(innerWidth - 350, sx + 16)) + 'px';\n  tipEl.style.top = Math.max(4, Math.min(innerHeight - 140, sy + 14)) + 'px';\n}\nfunction hideTip() { tipEl.style.display = 'none'; }\n\ncv.addEventListener('pointerdown', (ev) => {\n  userInteracted = true;\n  lastPointerType = ev.pointerType || 'mouse';\n  const n0 = pointers.size === 0 ? pick(ev.clientX, ev.clientY) : null;\n  pointers.set(ev.pointerId, {\n    x: ev.clientX, y: ev.clientY,\n    downX: ev.clientX, downY: ev.clientY, downT: performance.now(),\n    downNode: n0, moved: false, type: ev.pointerType || 'mouse',\n  });\n  if (pointers.size === 2) {\n    const [p1, p2] = [...pointers.values()];\n    pinch = {\n      d: Math.max(10, Math.hypot(p1.x - p2.x, p1.y - p2.y)),\n      mx: (p1.x + p2.x) / 2, my: (p1.y + p2.y) / 2,\n    };\n    dragNode = null; panning = null;\n    cv.classList.add('dragging');\n    return;\n  }\n  if (n0) { dragNode = n0; n0.vx = n0.vy = 0; hover = n0; wake(); } // hover = instant ring feedback, even for touch\n  else panning = { sx: ev.clientX, sy: ev.clientY, vx: view.x, vy: view.y, moved: false };\n  cv.classList.add('dragging');\n});\naddEventListener('pointermove', (ev) => {\n  const pe = pointers.get(ev.pointerId);\n  if (pe) {\n    pe.x = ev.clientX; pe.y = ev.clientY;\n    if (Math.hypot(pe.x - pe.downX, pe.y - pe.downY) > 9) pe.moved = true;\n  }\n  if (pinch && pointers.size === 2) {\n    const [p1, p2] = [...pointers.values()];\n    const nd = Math.max(10, Math.hypot(p1.x - p2.x, p1.y - p2.y));\n    const mx = (p1.x + p2.x) / 2, my = (p1.y + p2.y) / 2;\n    view.x += mx - pinch.mx; view.y += my - pinch.my;\n    const nk = Math.min(6, Math.max(0.08, view.k * (nd / pinch.d)));\n    view.x = mx - (mx - view.x) * (nk / view.k);\n    view.y = my - (my - view.y) * (nk / view.k);\n    view.k = nk;\n    pinch.d = nd; pinch.mx = mx; pinch.my = my;\n    return;\n  }\n  if (dragNode) {\n    const w = toWorld(ev.clientX, ev.clientY);\n    dragNode.x = w.x; dragNode.y = w.y; dragNode.vx = dragNode.vy = 0;\n    return;\n  }\n  if (panning) {\n    view.x = panning.vx + (ev.clientX - panning.sx);\n    view.y = panning.vy + (ev.clientY - panning.sy);\n    if (Math.abs(ev.clientX - panning.sx) + Math.abs(ev.clientY - panning.sy) > 4) panning.moved = true;\n    return;\n  }\n  if (ev.pointerType && ev.pointerType !== 'mouse' && ev.pointerType !== 'pen') return;\n  hover = pick(ev.clientX, ev.clientY);\n  if (hover) {\n    showTip(hover, ev.clientX, ev.clientY);\n    cv.style.cursor = 'pointer';\n  } else {\n    hideTip();\n    cv.style.cursor = 'grab';\n  }\n});\nfunction endPointer(ev) {\n  const entry = pointers.get(ev.pointerId);\n  pointers.delete(ev.pointerId);\n  cv.classList.remove('dragging');\n  if (pinch) {\n    if (pointers.size < 2) pinch = null;\n    dragNode = null; panning = null;\n    return;\n  }\n  dragNode = null; panning = null;\n  if (!entry) return;\n  /* Tap = press + release with almost no movement. Selection happens\n     HERE, in the pointerup path. v2 put selection ONLY in a `click`\n     listener, i.e. it depended on the browser synthesising a click on\n     the canvas after pointerup — and when that click never reaches the\n     canvas (as in the Android WebView on the user's phone), taps on\n     bubbles did absolutely nothing: the pointerup handler found\n     dragNode set and just returned. Reproduced headlessly: down+up\n     without click left the selection empty, for large and small\n     bubbles alike, while the draw/hit-test transforms were identical.\n     The click listener below is now only a deduped fallback. */\n  if (ev.type !== 'pointercancel' && !entry.moved && performance.now() - entry.downT < 800) {\n    lastTap = { t: performance.now(), x: ev.clientX, y: ev.clientY };\n    const n = pick(ev.clientX, ev.clientY);\n    if (n) selectNode(n);\n    else { clearSelection(); hover = null; hideTip(); }\n    return;\n  }\n  // Mouse/pen: releasing over the same bubble the press started on still\n  // selects it (the old click behaviour after a short drag).\n  if ((entry.type === 'mouse' || entry.type === 'pen') && entry.downNode &&\n      pick(ev.clientX, ev.clientY) === entry.downNode) {\n    selectNode(entry.downNode);\n  }\n}\naddEventListener('pointerup', endPointer);\naddEventListener('pointercancel', endPointer);\ncv.addEventListener('click', (ev) => {\n  // Fallback only — if the pointerup tap path already handled this exact\n  // tap, ignore the (possibly synthesised) click that trails it.\n  if (performance.now() - lastTap.t < 600 &&\n      Math.hypot(ev.clientX - lastTap.x, ev.clientY - lastTap.y) < 24) return;\n  const n = pick(ev.clientX, ev.clientY);\n  if (n) selectNode(n);\n});\ncv.addEventListener('wheel', (ev) => {\n  ev.preventDefault();\n  userInteracted = true;\n  const f = ev.deltaY < 0 ? 1.12 : 1 / 1.12;\n  const nk = Math.min(6, Math.max(0.08, view.k * f));\n  view.x = ev.clientX - (ev.clientX - view.x) * (nk / view.k);\n  view.y = ev.clientY - (ev.clientY - view.y) * (nk / view.k);\n  view.k = nk;\n}, { passive: false });\n\n/* ---------------- selection / panel ---------------- */\nfunction selectCluster(n) {\n  selectedCluster = n.cluster;\n  const members = [...clusterMembers.get(n.cluster)].sort((a, b) => b.balance - a.balance);\n  const total = members.reduce((s, m) => s + m.balance, 0);\n  const share = DATA.totalHoldersBalance42 > 0 ? (total / DATA.totalHoldersBalance42 * 100) : 0;\n  const valMembers = members.filter((m) => m.validator);\n  $('paneltitle').textContent = valMembers.length > 0\n    ? `バリデーター ${valMembers.map((m) => m.validator.moniker).join(' / ')} のクラスター`\n    : (members.length >= 2 ? `クラスター（${members.length} アドレス）` : '単独アドレス');\n  $('panelsum').innerHTML =\n    `合計保有量: <b>${fmt42(total)} 42</b><br>` +\n    `全保有量（残高ありアドレス合計）に占める割合: <b>${share.toFixed(3)}%</b><br>` +\n    `クラスター表示モード: ${MODE_LABELS[clusterMode]}`;\n  $('panelbody').innerHTML = members.map((m) =>\n    `<tr><td class=\"a\">${m.validator ? `<b style=\"color:#f5c542\">★ バリデーター: ${m.validator.moniker}</b><br>` : ''}${m.name ? `<b style=\"color:#f5c542\">${m.name}</b><br>` : ''}${m.address}</td><td class=\"b\">${fmt42(m.balance)}</td></tr>`\n  ).join('');\n  $('panel').style.display = 'block';\n}\nfunction clearSelection() {\n  selectedCluster = null;\n  selectedNode = null;\n  $('panel').style.display = 'none';\n  $('panelconn').innerHTML = '';\n}\n/* The selected node's own connections, each labelled EVM / Cosmos / both\n   with per-source counts and totals — the \"how is this address linked\"\n   view, sorted by total value moved. */\nfunction fillConnPanel(n) {\n  const el = $('panelconn');\n  const tot = (s) => (s.evm ? s.evm.totalValue42 : 0) + (s.cosmos ? s.cosmos.totalValue42 : 0);\n  const conns = [...(connByNode.get(n) || [])].sort((x, y) => tot(y.sources) - tot(x.sources));\n  const coreNote = n.distributor\n    ? `<div>中核パターン検出: 同じ額（${fmt42(n.distributor.amount42)} 42）を ${n.distributor.recipients} 件のアドレスへ送金しています${clusterMode === 'core' ? '（このモードでは中核としてクラスターから除外中）' : ''}</div>`\n    : '';\n  if (!conns.length) { el.innerHTML = coreNote; return; }\n  const MAXC = 40;\n  const rows = conns.slice(0, MAXC).map((c) => {\n    const o = c.other;\n    const who = o.validator ? `★ ${o.validator.moniker}` : (o.name || shortAddr(o.address));\n    return `<div>${who} — ${srcLabel(c.sources)}</div>`;\n  });\n  if (conns.length > MAXC) rows.push(`<div>…他 ${conns.length - MAXC} 件</div>`);\n  el.innerHTML = coreNote + `<b>${n.validator ? '★ ' + n.validator.moniker : shortAddr(n.address)}</b> のつながり（${conns.length} アドレス）:<br>` + rows.join('');\n}\n/* Select one bubble: cluster highlight + white ring on the bubble itself\n   + the info panel (a bottom sheet on phones, so the feedback is always\n   inside the visible area — the floating tooltip is mouse-hover only). */\nfunction selectNode(n) {\n  selectedNode = n;\n  hover = n;\n  selectCluster(n);\n  fillConnPanel(n);\n  if (lastPointerType !== 'mouse' && lastPointerType !== 'pen') hideTip();\n}\n$('panelclose').addEventListener('click', clearSelection);\n$('resetbtn').addEventListener('click', () => { clearSelection(); fitToBubbles(); $('searchmsg').textContent = ''; $('search').value = ''; });\n$('fitbtn').addEventListener('click', () => { fitToBubbles(); });\n\n/* ---------------- search ---------------- */\nfunction doSearch() {\n  const q = $('search').value.trim().toLowerCase();\n  const msg = $('searchmsg');\n  if (!q) { msg.textContent = ''; return; }\n  const n = byAddr.get(q);\n  if (!n) {\n    msg.textContent = 'このスナップショットには見つかりませんでした。';\n    return;\n  }\n  if (!nodeShown(n)) {\n    // Present in the data but filtered out by 「クラスターのみ」 —\n    // say so instead of silently failing (validators never land here).\n    msg.textContent = 'このアドレスは「クラスターのみ」表示で非表示になっています（単独アドレス）。表示するには「クラスターのみ」をオフにしてください。';\n    return;\n  }\n  msg.textContent = '';\n  view.k = Math.max(view.k, 0.9);\n  view.x = innerWidth / 2 - n.x * view.k;\n  view.y = innerHeight / 2 - n.y * view.k;\n  flashNode = n; flashUntil = performance.now() + 2600;\n  selectNode(n);\n}\n$('searchbtn').addEventListener('click', doSearch);\n$('search').addEventListener('keydown', (e) => { if (e.key === 'Enter') doSearch(); });\n\n/* ---------------- draw ---------------- */\nfunction draw(now) {\n  ctx.clearRect(0, 0, innerWidth, innerHeight);\n  ctx.save();\n  ctx.translate(view.x, view.y); ctx.scale(view.k, view.k);\n  const dimmed = selectedCluster !== null;\n  for (const e of edgeList) {\n    if (!nodeShown(e.a) || !nodeShown(e.b)) continue; // Mode E: hidden nodes lose their lines too\n    if (!hubLinesVisible && edgeTouchesHub(e)) continue; // hub lines off: bubbles stay, spokes go\n    if (!isFinite(e.a.x) || !isFinite(e.a.y) || !isFinite(e.b.x) || !isFinite(e.b.y)) continue;\n    const inSel = dimmed && e.a.cluster === selectedCluster && e.b.cluster === selectedCluster;\n    const hov = hover && (e.a === hover || e.b === hover);\n    const lw = (hov ? 2.2 : 1 + Math.min(2, e.count * 0.15)) / view.k * Math.max(1, view.k * 0.8);\n    ctx.globalAlpha = dimmed && !inSel && !hov ? 0.25 : 1;\n    /* Per-source strokes: EVM = pale blue, Cosmos = violet. A pair with\n       BOTH sources is drawn as a double line (wide EVM underlay + violet\n       core) so the two kinds of connection stay distinguishable. */\n    const hasE = !!e.sources.evm, hasC = !!e.sources.cosmos;\n    const stroke = (style, w) => {\n      ctx.strokeStyle = style; ctx.lineWidth = w;\n      ctx.beginPath(); ctx.moveTo(e.a.x, e.a.y); ctx.lineTo(e.b.x, e.b.y); ctx.stroke();\n    };\n    if (hasE) stroke(hov ? 'rgba(255,255,255,.85)' : inSel ? 'rgba(255,255,255,.5)' : 'rgba(160,190,255,.16)', hasC ? lw * 2 : lw);\n    if (hasC) stroke(hov ? 'rgba(255,255,255,.9)' : inSel ? 'rgba(216,180,255,.85)' : 'rgba(178,132,255,.55)', hasE ? lw * 0.85 : lw);\n  }\n  ctx.globalAlpha = 1;\n  const sorted = [...nodes].sort((a, b) => a.r - b.r);\n  for (const n of sorted) {\n    if (!nodeShown(n)) continue; // Mode E hidden singleton\n    if (!isFinite(n.x) || !isFinite(n.y)) continue;\n    const isSel = !dimmed || n.cluster === selectedCluster;\n    const isHov = hover === n;\n    const rr = drawRadiusW(n); // same radius mapping pick() uses — what you see is what you can tap\n    ctx.globalAlpha = isSel ? 1 : 0.18;\n    ctx.beginPath();\n    ctx.arc(n.x, n.y, rr, 0, Math.PI * 2);\n    ctx.fillStyle = n.color;\n    ctx.fill();\n    ctx.lineWidth = (isHov ? 2.6 : 1.2) / Math.max(0.6, view.k);\n    ctx.strokeStyle = isHov ? '#ffffff' : 'rgba(255,255,255,.45)';\n    ctx.stroke();\n    if (n.validator) {\n      const inv = 1 / Math.max(0.6, view.k);\n      ctx.beginPath();\n      ctx.arc(n.x, n.y, rr + 3 * inv, 0, Math.PI * 2);\n      ctx.lineWidth = 2.8 * inv;\n      ctx.strokeStyle = '#f5c542';\n      ctx.stroke();\n      const bs = Math.max(11, n.r * 0.55);\n      const bx = n.x + n.r * 0.74, by = n.y - n.r * 0.74;\n      ctx.beginPath();\n      ctx.arc(bx, by, bs * 0.62, 0, Math.PI * 2);\n      ctx.fillStyle = '#f5c542';\n      ctx.fill();\n      ctx.fillStyle = '#131a2a';\n      ctx.font = `700 ${bs}px sans-serif`;\n      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';\n      ctx.fillText('★', bx, by + bs * 0.08);\n    }\n    if (n === selectedNode) {\n      const invS = 1 / Math.max(view.k, 0.05);\n      ctx.beginPath();\n      ctx.arc(n.x, n.y, rr + 6 * invS, 0, Math.PI * 2);\n      ctx.lineWidth = 3 * invS;\n      ctx.strokeStyle = '#ffffff';\n      ctx.stroke();\n    }\n    if (flashNode === n && now < flashUntil) {\n      ctx.beginPath();\n      ctx.arc(n.x, n.y, n.r + 8 + 3 * Math.sin(now / 120), 0, Math.PI * 2);\n      ctx.strokeStyle = '#f5c542'; ctx.lineWidth = 3 / Math.max(0.6, view.k); ctx.stroke();\n    }\n    if (n.r * view.k > 15) {\n      ctx.fillStyle = 'rgba(4,8,18,.82)';\n      ctx.font = `700 ${Math.max(9, n.r * 0.34)}px sans-serif`;\n      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';\n      const label = n.name ? n.name.slice(0, 10) : shortAddr(n.address);\n      ctx.fillText(label, n.x, n.y - n.r * 0.16, n.r * 1.8);\n      ctx.font = `600 ${Math.max(8, n.r * 0.27)}px sans-serif`;\n      ctx.fillText(fmt42(n.balance), n.x, n.y + n.r * 0.28, n.r * 1.8);\n    }\n    if (n.validator && n.r * view.k > 24) {\n      ctx.fillStyle = '#f5c542';\n      ctx.font = `700 ${Math.max(10, n.r * 0.3)}px sans-serif`;\n      ctx.textAlign = 'center'; ctx.textBaseline = 'top';\n      ctx.fillText('★ ' + n.validator.moniker, n.x, n.y + rr + 7 / view.k, rr * 3.4);\n    }\n  }\n  ctx.restore();\n  ctx.globalAlpha = 1;\n}\n/* Warm up the simulation synchronously so the very first paint already\n   shows the settled scene, then fit the camera to the actual bubble\n   bounding box (v1 fitted a fixed 2400x1600 world exactly once, which on\n   portrait phones left the scene at k≈0.17 even before the sim blew up). */\ntry { for (let i = 0; i < 500; i++) step(); } catch (e) { /* draw guards still apply */ }\nsimRunning = false; stillFrames = 0;\nfitToBubbles();\nappStarted = true;\nfunction loop(now) {\n  requestAnimationFrame(loop); // schedule first: a frame error must never kill rendering\n  try {\n    if (cv.width === 0 || cv.height === 0 || innerWidth === 0 || innerHeight === 0) {\n      resize();\n      if (cv.width > 0 && cv.height > 0) fitToBubbles();\n      return;\n    }\n    if (simRunning) step();\n    draw(now || 0);\n  } catch (e) { /* transient error: the next frame retries */ }\n}\nrequestAnimationFrame(loop);\n\n/* ---------------- header meta ---------------- */\nfunction renderMeta() {\n  const evmN = DATA.edges.filter((e) => e.sources && e.sources.evm).length;\n  const cosmosN = DATA.edges.filter((e) => e.sources && e.sources.cosmos).length;\n  const bothN = DATA.edges.filter((e) => e.sources && e.sources.evm && e.sources.cosmos).length;\n  $('meta').innerHTML =\n    `スナップショット: <b>${fmtDate(DATA.fetchedAt)}</b><span class=\"m-opt\">（出典: Blockscout ${DATA.source.split(' ')[0]}）</span><br>` +\n    `表示中: <b>${DATA.nodes.length}</b> アドレス（上位150＋バリデーター関連は全件表示＋Cosmos側送金の参加者） / 残高ありアドレス総数 <b>${DATA.holdersWithBalance.toLocaleString('ja-JP')}</b><span class=\"m-opt\">（チェーン全体 ${DATA.chain.stats.totalAddresses.toLocaleString('ja-JP')}）</span><br>` +\n    `<span class=\"m-opt\">つながり（エッジ）: <b>${DATA.edges.length}</b> 件（EVM ${evmN} / Cosmos ${cosmosN}・両方 ${bothN}） / クラスター（${MODE_LABELS[clusterMode]}）: <b>${multiClusters.length}</b> グループ（最大 ${Math.max(...multiClusters.map((c) => c.members.length), 0)} アドレス）<br></span>` +\n    `表示中の合計保有量: <b>${fmt42(DATA.nodesBalance42)} 42</b>（残高ありアドレス合計 ${fmt42(DATA.totalHoldersBalance42)} 42 の ${(DATA.nodesBalance42 / DATA.totalHoldersBalance42 * 100).toFixed(1)}%）` +\n    (DATA.validators ? `<br>バリデーター: 全 <b>${DATA.validators.length}</b> 名中 <b>${DATA.nodes.filter((n) => n.validator).length}</b> 名を表示中（★マーク）` : ``) +\n    (DATA.cosmosTransfers ? `<br>Cosmos側送金: <b>${DATA.cosmosTransfers.legs}</b> 件（銀行送金の全履歴・全件取得）` : ``);\n}\nrenderMeta();\n\n/* ---------------- cluster mode toggle ----------------\n   Re-runs the coloring only: positions, physics, nodes and edges are\n   untouched, and an open selection is re-rendered under the new mode so\n   the panel/tap behaviour stays consistent. In-memory only (the page\n   persists no other UI state). */\nfunction applyClusterMode(mode) {\n  recluster(mode);\n  for (const m of Object.keys(MODE_LABELS)) {\n    const btn = $('mode-' + m);\n    if (btn) btn.classList.toggle('on', m === mode);\n  }\n  const mi = $('modeinfo');\n  if (mi) mi.textContent = MODE_INFO[mode];\n  /* Transparency in mode D: name the addresses excluded as core. */\n  const ci = $('coreinfo');\n  if (ci) {\n    if (mode === 'core') {\n      const distNames = nodes.filter((n) => n.distributor)\n        .map((n) => (n.validator ? '★' + n.validator.moniker : (n.name || shortAddr(n.address))));\n      const coreNames = nodes.filter((n) => isDesignatedCore(n))\n        .map((n) => DESIGNATED_CORE[n.address.toLowerCase()]);\n      const names = [...distNames, ...coreNames];\n      ci.textContent = names.length\n        ? `中核として除外中: 仕組み系コントラクト全般＋${names.join('＋')}`\n        : '中核として除外中: 仕組み系コントラクト全般';\n    } else ci.textContent = '';\n  }\n  /* Hub-line default follows the mode (hidden in D, where the hubs are\n     excluded as core; shown in A/B/C) — the header toggle can override\n     it in any mode until the next mode switch. */\n  setHubLines(mode !== 'core');\n  refreshFilterInfo();\n  renderMeta();\n  if (selectedNode && nodeShown(selectedNode)) selectNode(selectedNode);\n  else clearSelection();\n}\nfor (const m of Object.keys(MODE_LABELS)) {\n  const btn = $('mode-' + m);\n  if (btn) btn.addEventListener('click', () => { userInteracted = true; applyClusterMode(m); });\n}\n$('hubbtn').addEventListener('click', () => { userInteracted = true; setHubLines(!hubLinesVisible); });\n$('eonlybtn').addEventListener('click', () => { userInteracted = true; setClusterOnly(!clusterOnly); });\napplyClusterMode(clusterMode);\n</script>\n</body>\n</html>\n";
